                del report_struc['attachment']
            else:
                newattach = []
                for attachment in report_struc['attachment']:
                    newattach.append(report_struc['attachment'][attachment])
                report_struc['attachment'] = newattach

        newbody = []
        for _, body in bodys_struc.items():
            newbody.append(body)
        report_struc['body'] = newbody
        # End of dirty hack

        # Get all other bulk headers
        report_struc['header'] = headers_struc

        return report_struc

def noparenthesis(line: str) -> str:
    """Remove nested parentheses, until no pairs of matching parentyheses are present.

    Args:
        line (str): Input text to search in for parentheses.

    Returns:
        str: Return a string with all text in matching parentheses removed. For example,
        noparenthesis('a((b)c(d') == 'a(c(d'
    """
    fragments: list[list[str]] = [[]]
    for ch in line:
        if ch == '(':
            fragments.append([ch])
        else:
            fragments[-1].append(ch)
        if ch == ')' and len(fragments) > 1:
            fragments.pop()
    return ''.join(ch for w in fragments for ch in w)

