        # Validate JSON-RPC format
        if message.get("jsonrpc") != "2.0":
            return self._error_response(None, INVALID_REQUEST, "Invalid JSON-RPC version")

        method = message.get("method")
        params = message.get("params", {})
        msg_id = message.get("id")

        # Notifications don't have an id
        is_notification = msg_id is None

        # Handle initialized notification
        if method == "notifications/initialized":
            self._initialized = True
            logger.debug("Client sent initialized notification")
            return None

        # Handle cancellation notification
        if method == "notifications/cancelled":
            request_id = params.get("requestId")
            if request_id:
                self._cancelled_requests.add(str(request_id))
                if len(self._cancelled_requests) > self._max_cancelled_requests:
                    overflow = len(self._cancelled_requests) - self._max_cancelled_requests
                    for _ in range(overflow):
                        self._cancelled_requests.pop()
                # Cancel active task if exists
                if str(request_id) in self._active_requests:
                    task = self._active_requests[str(request_id)]
                    task.cancel()
                    logger.debug(f"Cancelled request: {request_id}")
            return None

        # Check if method exists
        handler = self._handlers.get(method)
        if handler is None:
            if is_notification:
                return None
            return self._error_response(msg_id, METHOD_NOT_FOUND, f"Method not found: {method}")

        # Execute handler
        try:
            result = await handler(params)
            if is_notification:
                return None
            return self._success_response(msg_id, result)
        except Exception as e:
            logger.exception(f"Error handling {method}")
            if is_notification:
                return None
            return self._error_response(msg_id, INTERNAL_ERROR, str(e))

def _validate_origin(self, request_origin: Optional[str]) -> bool:
        """
        Validate Origin header per MCP 2025-11-25 security requirements.

        Returns True if origin is valid or not present.
        Returns False if origin is present but invalid.
        """
        if request_origin is None:
            # No Origin header - allow (same-origin requests don't send Origin)
            return True

        if self.allowed_origins is None:
            # No allowed origins configured - reject all Origin headers
            return False

        from urllib.parse import urlparse
        from praisonaiagents.mcp.mcp_security import is_valid_origin

        allowed_hosts = []
        for origin in self.allowed_origins:
            host = urlparse(origin).hostname
            if host:
                allowed_hosts.append(host.lower())

        return is_valid_origin(request_origin, allowed_hosts, allow_missing=False)

