                if last_event_id and session_id in self._event_history:
                    history = self._event_history[session_id]
                    replay = False
                    for event_id, data in history:
                        if replay:
                            yield f"id:{event_id}\ndata:{data}\n\n"
                        elif event_id == last_event_id:
                            replay = True

