def _create_app(self):
        """Create the ASGI application."""
        try:
            from starlette.applications import Starlette
            from starlette.responses import JSONResponse, StreamingResponse
            from starlette.routing import Route
            from starlette.middleware.cors import CORSMiddleware
        except ImportError:
            logger.warning("Starlette not installed. Server features unavailable.")
            return None

        async def health(request):
            return JSONResponse({
                "status": "ok",
                "timestamp": time.time(),
                "clients": len(self._clients),
            })

        async def events(request):
            if not self._authorise_request(request):
                return JSONResponse({"error": "Unauthorized"}, status_code=401)
            client_id = str(uuid.uuid4())
            client = SSEClient(client_id)
            self._clients[client_id] = client

            logger.info(f"SSE client connected: {client_id}")

            async def event_generator():
                try:
                    for event in client.events():
                        yield event
                finally:
                    client.disconnect()
                    self._clients.pop(client_id, None)
                    logger.info(f"SSE client disconnected: {client_id}")

            return StreamingResponse(
                event_generator(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                },
            )

        async def publish(request):
            if not self._authorise_request(request):
                return JSONResponse({"error": "Unauthorized"}, status_code=401)
            try:
                data = await request.json()
                event_type = data.get("type", "message")
                event_data = data.get("data", {})

                self.broadcast(event_type, event_data)

                return JSONResponse({
                    "success": True,
                    "clients": len(self._clients),
                })
            except Exception as e:
                return JSONResponse(
                    {"success": False, "error": str(e)},
                    status_code=400
                )

        async def info(request):
            return JSONResponse({
                "name": "PraisonAI Agent Server",
                "version": "1.0.0",
                "clients": len(self._clients),
                "config": self.config.to_dict(),
            })

        routes = [
            Route("/health", health, methods=["GET"]),
            Route("/events", events, methods=["GET"]),
            Route("/publish", publish, methods=["POST"]),
            Route("/info", info, methods=["GET"]),
        ]

        app = Starlette(routes=routes)

        # Add CORS middleware
        app = CORSMiddleware(
            app,
            allow_origins=self.config.cors_origins,
            allow_methods=["GET", "POST", "OPTIONS"],
            allow_headers=["Authorization", "Content-Type", "Origin", "Accept"],
        )

        return app

