                logger.warning(f"Rejected request with invalid Origin: {origin}")
                return JSONResponse(
                    {"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Forbidden: Invalid Origin"}},
                    status_code=403,
                )

