                headers = {
                    "MCP-Session-Id": new_session_id,
                    "MCP-Protocol-Version": PROTOCOL_VERSION,
                }

                if response:
                    return JSONResponse(response, headers=headers)
                return Response(status_code=202, headers=headers)

