    class APIKeyAuthMiddleware(BaseHTTPMiddleware):
        """API Key authentication middleware."""

        async def dispatch(self, request, call_next):
            # Skip auth for health endpoint
            if request.url.path == "/health":
                return await call_next(request)

            # Check X-API-Key header
            provided_key = request.headers.get("X-API-Key")
            expected_key = api_key or os.environ.get("PRAISONAI_API_KEY")

            if not expected_key:
                # No key configured, allow request
                return await call_next(request)

            if not provided_key or not hmac.compare_digest(provided_key, expected_key):
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Invalid or missing API key"}},
                    status_code=401
                )

            return await call_next(request)

    class JWTAuthMiddleware(BaseHTTPMiddleware):
        """JWT authentication middleware."""

        async def dispatch(self, request, call_next):
            # Skip auth for health endpoint
            if request.url.path == "/health":
                return await call_next(request)

            # Get JWT secret
            secret = jwt_secret or os.environ.get("PRAISONAI_JWT_SECRET")
            if not secret:
                return await call_next(request)

            # Check Authorization header
            auth_header = request.headers.get("Authorization", "")
            if not auth_header.startswith("Bearer "):
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Missing or invalid Authorization header"}},
                    status_code=401
                )

            token = auth_header[7:]  # Remove "Bearer " prefix

            try:
                # Lazy import jwt
                import jwt as pyjwt
                payload = pyjwt.decode(token, secret, algorithms=["HS256"])
                # Store user info in request state
                request.state.user = payload
            except ImportError:
                return JSONResponse(
                    {"error": {"code": "server_error", "message": "JWT support not installed. Run: pip install PyJWT"}},
                    status_code=500
                )
            except pyjwt.ExpiredSignatureError:
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Token expired"}},
                    status_code=401
                )
            except pyjwt.InvalidTokenError as e:
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": f"Invalid token: {e}"}},
                    status_code=401
                )

            return await call_next(request)

    if auth_type == "api-key":
        return APIKeyAuthMiddleware
    elif auth_type == "jwt":
        return JWTAuthMiddleware

    return None

