def create_auth_middleware(auth_type: str, api_key: Optional[str] = None, jwt_secret: Optional[str] = None):
    """Create authentication middleware."""
    try:
        from starlette.middleware.base import BaseHTTPMiddleware
        from starlette.responses import JSONResponse
    except ImportError:
        return None

    class APIKeyAuthMiddleware(BaseHTTPMiddleware):
        """API Key authentication middleware."""

        async def dispatch(self, request, call_next):
            # Skip auth for health endpoint
            if request.url.path == "/health":
                return await call_next(request)

            # Check X-API-Key header
            provided_key = request.headers.get("X-API-Key")
            expected_key = api_key or os.environ.get("PRAISONAI_API_KEY")

            if not expected_key:
                return JSONResponse(
                    {"error": {"code": "misconfigured", "message": "API key authentication is enabled but no key is configured"}},
                    status_code=503,
                )

            if not provided_key or not hmac.compare_digest(provided_key, expected_key):
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Invalid or missing API key"}},
                    status_code=401
                )

            return await call_next(request)

    class JWTAuthMiddleware(BaseHTTPMiddleware):
        """JWT authentication middleware."""

        async def dispatch(self, request, call_next):
            # Skip auth for health endpoint
            if request.url.path == "/health":
                return await call_next(request)

            # Get JWT secret
            secret = jwt_secret or os.environ.get("PRAISONAI_JWT_SECRET")
            if not secret:
                return JSONResponse(
                    {"error": {"code": "misconfigured", "message": "JWT authentication is enabled but no secret is configured"}},
                    status_code=503,
                )

            # Check Authorization header
            auth_header = request.headers.get("Authorization", "")
            if not auth_header.startswith("Bearer "):
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Missing or invalid Authorization header"}},
                    status_code=401
                )

            token = auth_header[7:]  # Remove "Bearer " prefix

            try:
                # Lazy import jwt
                import jwt as pyjwt
                payload = pyjwt.decode(token, secret, algorithms=["HS256"])
                # Store user info in request state
                request.state.user = payload
            except ImportError:
                return JSONResponse(
                    {"error": {"code": "server_error", "message": "JWT support not installed. Run: pip install PyJWT"}},
                    status_code=500
                )
            except pyjwt.ExpiredSignatureError:
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": "Token expired"}},
                    status_code=401
                )
            except pyjwt.InvalidTokenError as e:
                return JSONResponse(
                    {"error": {"code": "unauthorized", "message": f"Invalid token: {e}"}},
                    status_code=401
                )

            return await call_next(request)

    if auth_type == "api-key":
        return APIKeyAuthMiddleware
    elif auth_type == "jwt":
        return JWTAuthMiddleware

    return None

def _create_app(self):
        """Create the ASGI application."""
        try:
            from starlette.applications import Starlette
            from starlette.responses import JSONResponse, StreamingResponse
            from starlette.routing import Route
            from starlette.middleware.cors import CORSMiddleware
        except ImportError:
            logger.warning("Starlette not installed. Server features unavailable.")
            return None

        async def health(request):
            return JSONResponse({
                "status": "ok",
                "timestamp": time.time(),
                "clients": len(self._clients),
            })

        async def events(request):
            if not self._authorise_request(request):
                return JSONResponse({"error": "Unauthorized"}, status_code=401)
            client_id = str(uuid.uuid4())
            client = SSEClient(client_id)
            self._clients[client_id] = client

            logger.info(f"SSE client connected: {client_id}")

            async def event_generator():
                try:
                    for event in client.events():
                        yield event
                finally:
                    client.disconnect()
                    self._clients.pop(client_id, None)
                    logger.info(f"SSE client disconnected: {client_id}")

            return StreamingResponse(
                event_generator(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                },
            )

        async def publish(request):
            if not self._authorise_request(request):
                return JSONResponse({"error": "Unauthorized"}, status_code=401)
            try:
                data = await request.json()
                event_type = data.get("type", "message")
                event_data = data.get("data", {})

                self.broadcast(event_type, event_data)

                return JSONResponse({
                    "success": True,
                    "clients": len(self._clients),
                })
            except Exception as e:
                return JSONResponse(
                    {"success": False, "error": str(e)},
                    status_code=400
                )

        async def info(request):
            return JSONResponse({
                "name": "PraisonAI Agent Server",
                "version": "1.0.0",
                "clients": len(self._clients),
                "config": self.config.to_dict(),
            })

        routes = [
            Route("/health", health, methods=["GET"]),
            Route("/events", events, methods=["GET"]),
            Route("/publish", publish, methods=["POST"]),
            Route("/info", info, methods=["GET"]),
        ]

        app = Starlette(routes=routes)

        # Add CORS middleware
        app = CORSMiddleware(
            app,
            allow_origins=self.config.cors_origins,
            allow_methods=["GET", "POST", "OPTIONS"],
            allow_headers=["Authorization", "Content-Type", "Origin", "Accept"],
        )

        return app

